INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/find-bugs', 'find-bugs', 'getsentry', 'skills', 'official', 'find-bugs getsentry skills official tag-production find-bugs find-bugs find-bugs El agente de habilidad ''find-bugs'' analiza los cambios en la rama local para detectar errores, vulnerabilidades de seguridad y problemas de calidad de código. L''agent de compétence ''find-bugs'' analyse les modifications de la branche locale pour détecter les erreurs, les vulnérabilités de sécurité et les problèmes de qualité de code. Der ''find-bugs''-Agent analysiert die Änderungen des lokalen Branches, um Fehler, Sicherheitslücken und Codequalitätsprobleme zu erkennen. A habilidade de encontrar bugs ajuda a identificar problemas de código, melhorando a qualidade e segurança do software Навык поиска ошибок помогает выявить проблемы кода, улучшая качество и безопасность программного обеспечения مهارة اكتشاف الأخطاء تساعد في تحديد مشاكل الكود مما يحسن جودة وأمان البرمجيات Find bugs, security vulnerabilities, and code quality issues in local branch changes. Use when asked to review changes, find bugs, security review, or audit code on the current branch. find-bugs find-bugs find-bugs find-bugs find-bugs find-bugs Find bugs, security vulnerabilities, and code quality issues in local branch changes. Use when asked to review changes, find bugs, security review, or audit code on the current branch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('supabase/agent-skills/supabase-postgres-best-practices', 'official', 'supabase', 'agent-skills', 'supabase/agent-skills', 'supabase-postgres-best-practices', 1469, 85, 79, '2026-03-02T07:15:27Z', '2026-03-02T07:36:02.450Z', '8e5a86aa92990a706512a6454e3a6a6345a950b454e75a11d048210d0a2ca830', '{"id":"supabase/agent-skills/supabase-postgres-best-practices","name":"supabase-postgres-best-practices","description":{"zh":"Supabase Postgres 优化最佳实践，为开发者提供Postgres性能优化和最佳实践指南","ja":"Supabase Postgres 最適化ベストプラクティス、開発者向けのPostgresパフォーマンス最適化とベストプラクティスのガイド","ko":"Supabase Postgres 최적화 모범 사례 개발자를 위한 Postgres 성능 최적화 및 모범 사례 가이드","es":"Guía de optimización de rendimiento de Postgres de Supabase. Contiene reglas en 8 categorías para guiar la optimización automática de consultas y diseño de esquemas","fr":"Guide d''optimisation des performances de Postgres de Supabase. Contient des règles dans 8 catégories pour guider l''optimisation automatique des requêtes et la conception de schémas","de":"Leitfaden zur Leistungsoptimierung von Postgres von Supabase. Enthält Regeln in 8 Kategorien zur Steuerung der automatischen Abfrageoptimierung und Schemadesign","pt":"Guia de otimização de desempenho do Postgres, mantido pela Supabase. Contém regras em 8 categorias para otimização automática de consultas e design de esquemas","ru":"Руководство по оптимизации производительности Postgres, поддерживаемое Supabase. Содержит правила в 8 категориях для автоматической оптимизации запросов и проектирования схем","ar":"دليل تحسين أداء Postgres، الذي تحتفظ به Supabase. يحتوي على قواعد في 8 فئات لتحسين استفسارات وتخطيط المخططات تلقائيًا","en":"Postgres performance optimization and best practices from Supabase. Use this skill when writing, reviewing, or optimizing Postgres queries, schema designs, or database configurations."},"owner":"supabase","repo":"agent-skills","repoPath":"supabase/agent-skills","stars":1469,"forks":85,"updatedAt":"2026-03-02T07:15:27Z","topics":["ai","ai-agents","skills","supabase"],"skillMd":{"name":"supabase-postgres-best-practices","description":"Postgres performance optimization and best practices from Supabase. Use this skill when writing, reviewing, or optimizing Postgres queries, schema designs, or database configurations.","version":"1.1.0","bodyPreview":"# Supabase Postgres Best Practices\n\nComprehensive performance optimization guide for Postgres, maintained by Supabase. Contains rules across 8 categories, prioritized by impact to guide automated query optimization and schema design.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing SQL queries or designing schemas\n- Implementing indexes or query optimization\n- Reviewing database performance issues\n- Configuring connection pooling or scaling\n- Optimizing for Postgres-specific feature","body":"# Supabase Postgres Best Practices\n\nComprehensive performance optimization guide for Postgres, maintained by Supabase. Contains rules across 8 categories, prioritized by impact to guide automated query optimization and schema design.\n\n## When to Apply\n\nReference these guidelines when:\n- Writing SQL queries or designing schemas\n- Implementing indexes or query optimization\n- Reviewing database performance issues\n- Configuring connection pooling or scaling\n- Optimizing for Postgres-specific features\n- Working with Row-Level Security (RLS)\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Query Performance | CRITICAL | `query-` |\n| 2 | Connection Management | CRITICAL | `conn-` |\n| 3 | Security & RLS | CRITICAL | `security-` |\n| 4 | Schema Design | HIGH | `schema-` |\n| 5 | Concurrency & Locking | MEDIUM-HIGH | `lock-` |\n| 6 | Data Access Patterns | MEDIUM | `data-` |\n| 7 | Monitoring & Diagnostics | LOW-MEDIUM | `monitor-` |\n| 8 | Advanced Features | LOW | `advanced-` |\n\n## How to Use\n\nRead individual rule files for detailed explanations and SQL examples:\n\n```\nreferences/query-missing-indexes.md\nreferences/schema-partial-indexes.md\nreferences/_sections.md\n```\n\nEach rule file contains:\n- Brief explanation of why it matters\n- Incorrect SQL example with explanation\n- Correct SQL example with explanation\n- Optional EXPLAIN output or metrics\n- Additional context and references\n- Supabase-specific notes (when applicable)\n\n## References\n\n- https://www.postgresql.org/docs/current/\n- https://supabase.com/docs\n- https://wiki.postgresql.org/wiki/Performance_Optimization\n- https://supabase.com/docs/guides/database/overview\n- https://supabase.com/docs/guides/auth/row-level-security\n"},"category":"official","lastSynced":"2026-03-02T07:36:02.450Z","seo":{"title":{"zh":"Supabase Postgres 优化最佳实践 - AI工具","ja":"Supabase Postgres 最適化ベストプラクティス - AIエージェント","ko":"Supabase Postgres 최적화 모범 사례 - AI 에이전트","es":"Herramientas AI: Mejores prácticas de Supabase Postgres","fr":"Outils IA: Bonnes pratiques Supabase Postgres","de":"KI-Tools: Supabase Postgres Best Practices","pt":"Melhores Práticas Supabase Postgres - Ferramentas de IA","ru":"Supabase Postgres Лучшие Практики - ИИ Агенты","ar":"أفضل ممارسات Supabase Postgres - أدوات الذكاء الاصطناعي","en":"supabase-postgres-best-practices"},"description":{"zh":"Supabase Postgres 优化最佳实践，为开发者提供Postgres性能优化和最佳实践指南","ja":"Supabase Postgres 最適化ベストプラクティス、開発者向けのPostgresパフォーマンス最適化とベストプラクティスのガイド","ko":"Supabase Postgres 최적화 모범 사례 개발자를 위한 Postgres 성능 최적화 및 모범 사례 가이드","es":"Guía de optimización de rendimiento de Postgres de Supabase. Contiene reglas en 8 categorías para guiar la optimización automática de consultas y diseño de e...","fr":"Guide d''optimisation des performances de Postgres de Supabase. Contient des règles dans 8 catégories pour guider l''optimisation automatique des requêtes et l...","de":"Leitfaden zur Leistungsoptimierung von Postgres von Supabase. Enthält Regeln in 8 Kategorien zur Steuerung der automatischen Abfrageoptimierung und Schemadesign","pt":"Guia de otimização de desempenho do Postgres, mantido pela Supabase. Contém regras em 8 categorias para otimização automática de consultas e design de esquemas","ru":"Руководство по оптимизации производительности Postgres, поддерживаемое Supabase. Содержит правила в 8 категориях для автоматической оптимизации запросов и пр...","ar":"دليل تحسين أداء Postgres، الذي تحتفظ به Supabase. يحتوي على قواعد في 8 فئات لتحسين استفسارات وتخطيط المخططات تلقائيًا","en":"Postgres performance optimization and best practices from Supabase. Use this skill when writing, reviewing, or optimizing Postgres queries, schema designs, o..."},"definition":{"en":"Postgres performance optimization and best practices from Supabase. Use this skill when writing, reviewing, or optimizing Postgres queries, schema designs, or database configurations."},"features":{"zh":["Postgres 性能优化","SQL 查询优化","数据库配置优化","索引优化","连接池优化","扩展优化"],"ja":["Postgres パフォーマンス最適化","SQL クエリ最適化","データベース構成最適化","インデックス最適化","接続プール最適化","拡張最適化"],"ko":["Postgres 성능 최적화","SQL 쿼리 최적화","데이터베이스 구성 최적화","인덱스 최적화","연결 풀 최적화","확장 최적화"],"es":["Optimización de consultas SQL","Diseño de esquemas óptimos","Implementación de índices y optimización de consultas","Revisión de problemas de rendimiento de la base de datos","Configuración de agrupación de conexiones y escalado"],"fr":["Optimisation des requêtes SQL","Conception de schémas optimaux","Mise en œuvre d''index et d''optimisation de requêtes","Révision des problèmes de performances de la base de données","Configuration du regroupement de connexions et du scaling"],"de":["Optimierung von SQL-Abfragen","Optimales Schemadesign","Implementierung von Indizes und Abfrageoptimierung","Überprüfung von Datenbankleistungsproblemen","Konfiguration von Verbindungspooling und Skalierung"],"pt":["Otimização de consultas SQL","Design de esquemas de banco de dados","Implementação de índices","Otimização de desempenho do Postgres","Configuração de pool de conexões","Escala de banco de dados"],"ru":["Оптимизация запросов SQL","Проектирование схем баз данных","Реализация индексов","Оптимизация производительности Postgres","Настройка пула соединений","Масштабирование баз данных"],"ar":["تحسين استفسارات SQL","تصميم مخططات قواعد البيانات","تنفيذ الفهارس","تحسين أداء Postgres","تكوين مجموعة الاتصال","توسيع قواعد البيانات"]},"keywords":{"zh":["Supabase","Postgres","AI工具","性能优化","SQL查询","数据库配置","索引优化","连接池"],"ja":["Supabase","Postgres","AIエージェント","パフォーマンス最適化","SQLクエリ","データベース構成","インデックス最適化","接続プール"],"ko":["Supabase","Postgres","AI 에이전트","성능 최적화","SQL 쿼리","데이터베이스 구성","인덱스 최적화","연결 풀"],"es":["Herramientas AI","Mejores prácticas de Postgres","Optimización de rendimiento","Diseño de esquemas","Consultas SQL","Índices y optimización de consultas"],"fr":["Outils IA","Bonnes pratiques de Postgres","Optimisation des performances","Conception de schémas","Requêtes SQL","Index et optimisation de requêtes"],"de":["KI-Tools","Best Practices von Postgres","Leistungsoptimierung","Schemadesign","SQL-Abfragen","Indizes und Abfrageoptimierung"],"pt":["Supabase","Postgres","Otimização de desempenho","Melhores práticas","Desenvolvimento de banco de dados","Consultas SQL","Esquemas de banco de dados","Índices","Pool de conexões"],"ru":["Supabase","Postgres","Оптимизация производительности","Лучшие практики","Разработка баз данных","Запросы SQL","Схемы баз данных","Индексы","Пул соединений"],"ar":["Supabase","Postgres","تحسين الأداء","أفضل الممارسات","تطوير قواعد البيانات","استفسارات SQL","مخططات قواعد البيانات","الفهارس","مجموعة الاتصال"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Database Optimization Agents needing advanced Postgres performance tuning and best practices from Supabase.","zh":"非常适合需要高级Postgres性能优化和Supabase最佳实践的数据库优化代理","ja":"Supabaseからの高度なPostgresパフォーマンスチューニングとベストプラクティスを必要とするデータベース最適化エージェントに最適","ko":"Supabase의 고급 Postgres 성능 최적화 및 모범 사례가 필요한 데이터베이스 최적화 에이전트에 적합","es":"Perfecto para Agentes de Optimización de Base de Datos que necesitan una configuración avanzada de rendimiento de Postgres y mejores prácticas de Supabase.","fr":"Parfait pour les agents d''optimisation de base de données nécessitant une configuration avancée des performances Postgres et les meilleures pratiques de Supabase.","de":"Perfekt für Datenbank-Optimierungsagenten, die eine erweiterte Postgres-Leistungsanpassung und Best Practices von Supabase benötigen.","pt":"Perfeito para Agentes de Otimização de Banco de Dados que necessitam de ajustes avançados de desempenho do Postgres e melhores práticas da Supabase.","ru":"Идеально подходит для агентов оптимизации базы данных, которым необходимы продвинутые настройки производительности Postgres и лучшие практики от Supabase.","ar":"مثالي للوكلاء المحتاجين إلى تحسين أداء قاعدة البيانات المتقدمة وتحسين أداء البوستجرس وأفضل الممارسات من سوبربيس."},"recommendation":{"en":"Empowers agents to optimize Postgres queries, schema designs, and database configurations using rules across 8 categories, prioritized by impact, and leveraging connection pooling and scaling for improved performance, all while implementing indexes or query optimization for Postgres-specific features.","zh":"赋予代理优化Postgres查询、模式设计和数据库配置的能力，使用8个类别的规则，根据影响力优先，并利用连接池和扩展来提高性能，同时实现索引或查询优化以适应Postgres特定的功能","ja":"エージェントがPostgresクエリ、スキーマデザイン、データベース構成を最適化する機能を提供し、8つのカテゴリのルールを使用して影響力に基づいて優先順位付けを行い、接続プールとスケーリングを利用してパフォーマンスを向上させ、Postgres固有の機能向けのインデックスまたはクエリ最適化を実装する","ko":"에이전트가 Postgres 쿼리, 스키마 디자인 및 데이터베이스 구성 최적화를 가능하게 함, 8개 범주의 규칙을 사용하여 영향을 기준으로 우선순위를 정함, 연결 풀링 및 확장 기능을 활용하여 성능을 개선함, Postgres 고유의 기능을 위한 인덱스 또는 쿼리 최적화를 구현함","es":"Habilita a los agentes a optimizar consultas de Postgres, diseños de esquema y configuraciones de base de datos utilizando reglas en 8 categorías, priorizadas por impacto, y aprovechando la agrupación de conexiones y la escalabilidad para un mejor rendimiento, todo mientras se implementan índices u optimización de consultas para características específicas de Postgres.","fr":"Permet aux agents d''optimiser les requêtes Postgres, les conceptions de schéma et les configurations de base de données en utilisant des règles dans 8 catégories, priorisées par impact, et en exploitant le regroupement de connexions et la mise à l''échelle pour de meilleures performances, tout en mettant en œuvre des index ou une optimisation de requête pour les fonctionnalités spécifiques à Postgres.","de":"Ermächtigt Agenten, Postgres-Abfragen, Schemadesigns und Datenbankkonfigurationen zu optimieren, indem Regeln in 8 Kategorien verwendet werden, die nach Auswirkung priorisiert und die Verbindungspooling und Skalierbarkeit für eine verbesserte Leistung nutzen, während Indizes oder Abfrageoptimierungen für Postgres-spezifische Funktionen implementiert werden.","pt":"Habilita os agentes a otimizar consultas Postgres, projetos de esquema e configurações de banco de dados usando regras em 8 categorias, priorizadas por impacto, e aproveitando o pooling de conexões e escalabilidade para melhorar o desempenho, tudo isso implementando índices ou otimização de consultas para recursos específicos do Postgres.","ru":"Наделяет агентов возможностью оптимизировать запросы Postgres, схемы проектирования и конфигурации базы данных, используя правила в 8 категориях, отсортированные по влиянию, и используя пулинг подключений и масштабируемость для улучшения производительности, а также реализуя индексы или оптимизацию запросов для функций, специфичных для Postgres.","ar":"تمكّن الوكلاء من تحسين استفسارات البوستجرس وتصاميم مخطط البيانات وتكوين قاعدة البيانات باستخدام القواعد عبر 8 فئات، مصنفة حسب التأثير، واستغلال مجموعة الاتصال وتوسيع النطاق لتحسين الأداء، مع تنفيذ الفهارس أو تحسين الاستفسار لسمات البوستجرس الخاصة."},"useCases":{"en":["Optimizing Postgres queries for better performance","Implementing efficient schema designs and indexing strategies","Reviewing and resolving database performance issues using Supabase guidelines"],"zh":["优化Postgres查询以获得更好的性能","实施高效的模式设计和索引策略","使用Supabase指南审查和解决数据库性能问题"],"ja":["より良いパフォーマンスを得るためにPostgresクエリを最適化する","効率的なスキーマデザインとインデックス戦略を実装する","Supabaseのガイドラインを使用してデータベースパフォーマンスの問題をレビューして解決する"],"ko":["より 나은 성능을 위해 Postgres 쿼리를 최적화","효율적인 스키마 디자인 및 인덱스 전략을 구현","Supabase 가이드라인을 사용하여 데이터베이스 성능 문제를 검토 및 해결"],"es":["Optimizar consultas de Postgres para un mejor rendimiento","Implementar diseños de esquema eficientes y estrategias de indexación","Revisar y resolver problemas de rendimiento de la base de datos utilizando las directrices de Supabase"],"fr":["Optimiser les requêtes Postgres pour de meilleures performances","Mettre en œuvre des conceptions de schéma efficaces et des stratégies d''indexation","Examiner et résoudre les problèmes de performances de la base de données en utilisant les lignes directrices de Supabase"],"de":["Postgres-Abfragen für eine bessere Leistung optimieren","Effiziente Schemadesigns und Indexierungsstrategien implementieren","Datenbankleistungsprobleme unter Verwendung der Supabase-Richtlinien überprüfen und lösen"],"pt":["Otimizando consultas Postgres para melhor desempenho","Implementando projetos de esquema eficientes e estratégias de indexação","Revisando e resolvendo problemas de desempenho do banco de dados usando diretrizes da Supabase"],"ru":["Оптимизация запросов Postgres для лучшей производительности","Реализация эффективных схем проектирования и стратегий индексирования","Проверка и решение проблем производительности базы данных, используя руководящие принципы Supabase"],"ar":["تحسين استفسارات البوستجرس من أجل أداء أفضل","تنفيذ مخططات مخطط البيانات الكفء و استراتيجيات الفهرسة","مراجعة وحل مشاكل أداء قاعدة البيانات باستخدام إرشادات سوبربيس"]},"limitations":{"en":["Requires knowledge of SQL and Postgres database management","Specific to Postgres databases, may not be applicable to other database systems","Dependent on Supabase maintenance and updates for best practices"],"zh":["需要SQL和Postgres数据库管理知识","特定于Postgres数据库，可能不适用于其他数据库系统","依赖于Supabase的维护和更新以获取最佳实践"],"ja":["SQLとPostgresデータベース管理の知識が必要","Postgresデータベース専用であり、他のデータベースシステムには適用できない可能性がある","ベストプラクティスを取得するためにはSupabaseのメンテナンスと更新に依存する"],"ko":["SQL 및 Postgres 데이터베이스 관리 지식 필요","Postgres 데이터베이스 전용, 다른 데이터베이스 시스템에는 적용되지 않을 수 있음","최적의 성능을 얻기 위해 Supabase의 유지 보수 및 업데이트에 의존"],"es":["Requiere conocimiento de SQL y administración de bases de datos Postgres","Específico para bases de datos Postgres, puede que no sea aplicable a otros sistemas de bases de datos","Dependiente del mantenimiento y las actualizaciones de Supabase para las mejores prácticas"],"fr":["Nécessite des connaissances en SQL et en administration de bases de données Postgres","Spécifique aux bases de données Postgres, peut ne pas être applicable à d''autres systèmes de bases de données","Dépendant de la maintenance et des mises à jour de Supabase pour les meilleures pratiques"],"de":["Benötigt Kenntnisse von SQL und Postgres-Datenbankverwaltung","Spezifisch für Postgres-Datenbanken, möglicherweise nicht auf andere Datenbanksysteme anwendbar","Von der Wartung und den Updates von Supabase für die besten Praktiken abhängig"],"pt":["Exige conhecimento de SQL e gerenciamento de banco de dados Postgres","Específico para bancos de dados Postgres, pode não ser aplicável a outros sistemas de banco de dados","Depende da manutenção e atualizações da Supabase para as melhores práticas"],"ru":["Требует знания SQL и управления базой данных Postgres","Спецефичен для баз данных Postgres, может не быть применим к другим системам баз данных","Зависит от обслуживания и обновлений Supabase для лучших практик"],"ar":["يتطلب معرفة SQL وإدارة قاعدة البيانات البوستجرس","محدد لقاعدة البيانات البوستجرس، قد لا يكون قابلاً للتطبيق على أنظمة قاعدة البيانات الأخرى","يعتمد على صيانة وتحديثات سوبربيس لأفضل الممارسات"]},"version":3},"contentHash":"8e5a86aa92990a706512a6454e3a6a6345a950b454e75a11d048210d0a2ca830","repoEtag":"W/\"47701a9518842851006c992c8a046a323ae6f2fb6f48c90ffd34673ba499ffd0\"","qualityScore":79}');
