INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/extract-errors', 'extract-errors', 'facebook', 'react', 'official', 'extract-errors facebook react official declarative frontend javascript library react ui extract-errors AI工具帮助您提取React错误代码并保持更新 extract-errors AIエージェントは、Reactのエラーコードを抽出して最新に保ちます extract-errors AI 에이전트는 React 오류 코드를 추출하고 최신 상태로 유지합니다 La herramienta de extracción de errores ayuda a identificar y asignar códigos a nuevos mensajes de error en React L''outil d''extraction d''erreurs aide à identifier et à attribuer des codes aux nouveaux messages d''erreur dans React Das Fehler-Extraktions-Tool hilft bei der Identifizierung und Zuweisung von Codes zu neuen Fehlermeldungen in React O agente extract-errors é uma ferramenta de IA que ajuda a extrair códigos de erro em React. Ele é útil ao adicionar novas mensagens de erro ou ao ver avisos de códigos de erro desconhecidos ИИ Агент extract-errors - это инструмент, который помогает извлечь коды ошибок в React. Он полезен при добавлении новых сообщений об ошибках или при просмотре предупреждений о неизвестных кодах ошибок أداة الذكاء الاصطناعي extract-errors هي أداة تساعد على استخراج رموز الأخطاء في React. وهي مفيدة عند إضافة رسائل خطأ جديدة أو عند مشاهدة تحذيرات من رموز أخطاء غير معروفة Use when adding new error messages to React, or seeing unknown error code warnings. AI工具 React错误代码 extract-errors yarn javascript 前端开发 Use when adding new error messages to React, or seeing unknown error code warnings.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/fix', 'official', 'facebook', 'react', 'facebook/react', 'fix', 243408, 50622, 73, '2026-03-02T07:19:32Z', '2026-03-02T07:37:51.256Z', 'a2edb0e8fb758efe98df7a4bc2bab1d82e46b1b40a5ad9cd45b60f44730e7c32', '{"id":"facebook/react/fix","name":"fix","description":{"zh":"fix代码修复工具，用于解决lint错误和格式问题，确保代码通过CI","ja":"コード修正ツールfixは、lintエラーとフォーマット問題を解決し、コードがCIを通過できるようにします","ko":"코드 수정 도구 fix는 lint 오류 및 형식 문제를 해결하여 코드가 CI를 통과할 수 있도록 합니다","es":"La habilidad de reparación de código es una herramienta para corregir errores de lint y formato en proyectos de React y JavaScript","fr":"La compétence de correction de code est un outil pour corriger les erreurs de lint et de format dans les projets React et JavaScript","de":"Die Code-Reparaturfähigkeit ist ein Tool zum Korrigieren von Lint- und Formatierungsfehlern in React- und JavaScript-Projekten","pt":"O agente de fix ajuda a corrigir erros de lint e formatação no seu código React e JavaScript, garantindo a qualidade e a consistência","ru":"Агент исправления помогает исправить ошибки lint и форматирования в вашем коде React и JavaScript, гарантируя качество и согласованность","ar":"وكيل الإصلاح يساعد في تصحيح أخطاء لينت وتشكيل في رمزك React وJavaScript، ضامنًا الجودة والاتساق","en":"Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI."},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243408,"forks":50622,"updatedAt":"2026-03-02T07:19:32Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"fix","description":"Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI.","bodyPreview":"# Fix Lint and Formatting\n\n## Instructions\n\n1. Run `yarn prettier` to fix formatting\n2. Run `yarn linc` to check for remaining lint issues\n3. Report any remaining manual fixes needed\n\n## Common Mistakes\n\n- **Running prettier on wrong files** - `yarn prettier` only formats changed files\n- **Ignoring linc errors** - These will fail CI, fix them before committing","body":"# Fix Lint and Formatting\n\n## Instructions\n\n1. Run `yarn prettier` to fix formatting\n2. Run `yarn linc` to check for remaining lint issues\n3. Report any remaining manual fixes needed\n\n## Common Mistakes\n\n- **Running prettier on wrong files** - `yarn prettier` only formats changed files\n- **Ignoring linc errors** - These will fail CI, fix them before committing\n"},"category":"official","lastSynced":"2026-03-02T07:37:51.256Z","seo":{"title":{"zh":"AI工具：代码修复","ja":"AIエージェント：コード修正","ko":"AI 에이전트: 코드 수정","es":"Herramientas de reparación de código para React y JavaScript","fr":"Outils de correction de code pour React et JavaScript","de":"Code-Reparatur-Tools für React und JavaScript","pt":"Ferramentas de IA: Corrija Erros de Lint e Formatação","ru":"ИИ Агенты: Исправьте ошибки lint и форматирования","ar":"أدوات الذكاء الاصطناعي: إصلاح أخطاء لينت وتشكيل","en":"fix"},"description":{"zh":"fix代码修复工具，用于解决lint错误和格式问题，确保代码通过CI","ja":"コード修正ツールfixは、lintエラーとフォーマット問題を解決し、コードがCIを通過できるようにします","ko":"코드 수정 도구 fix는 lint 오류 및 형식 문제를 해결하여 코드가 CI를 통과할 수 있도록 합니다","es":"La habilidad de reparación de código es una herramienta para corregir errores de lint y formato en proyectos de React y JavaScript","fr":"La compétence de correction de code est un outil pour corriger les erreurs de lint et de format dans les projets React et JavaScript","de":"Die Code-Reparaturfähigkeit ist ein Tool zum Korrigieren von Lint- und Formatierungsfehlern in React- und JavaScript-Projekten","pt":"O agente de fix ajuda a corrigir erros de lint e formatação no seu código React e JavaScript, garantindo a qualidade e a consistência","ru":"Агент исправления помогает исправить ошибки lint и форматирования в вашем коде React и JavaScript, гарантируя качество и согласованность","ar":"وكيل الإصلاح يساعد في تصحيح أخطاء لينت وتشكيل في رمزك React وJavaScript، ضامنًا الجودة والاتساق","en":"Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI."},"definition":{"en":"Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI."},"features":{"zh":["运行yarn prettier修复格式问题","运行yarn linc检查剩余的lint问题","报告需要手动修复的代码","支持React和JavaScript","确保代码通过CI"],"ja":["yarn prettierを実行してフォーマット問題を修正","yarn lincを実行して残りのlint問題をチェック","手動で修正する必要があるコードを報告","ReactとJavaScriptをサポート","コードがCIを通過できるようにする"],"ko":["yarn prettier를 실행하여 형식 문제를 수정","yarn linc를 실행하여 남은 lint 문제를 확인","수동으로 수정해야 하는 코드를 보고","React 및 JavaScript를 지원","코드가 CI를 통과할 수 있도록 함"],"es":["Corrección de errores de lint","Corrección de errores de formato","Soporte para proyectos de React y JavaScript","Integración con yarn prettier y yarn linc","Informes de correcciones manuales necesarias"],"fr":["Correction des erreurs de lint","Correction des erreurs de format","Prise en charge des projets React et JavaScript","Intégration avec yarn prettier et yarn linc","Rapports de corrections manuelles nécessaires"],"de":["Korrigieren von Lint-Fehlern","Korrigieren von Formatierungsfehlern","Unterstützung für React- und JavaScript-Projekte","Integration mit yarn prettier und yarn linc","Berichte über erforderliche manuelle Korrekturen"],"pt":["Correção de erros de lint","Formatação de código","Compatibilidade com React e JavaScript","Integração com yarn prettier","Relatórios de erros e correções"],"ru":["Исправление ошибок lint","Форматирование кода","Совместимость с React и JavaScript","Интеграция с yarn prettier","Отчеты об ошибках и исправлениях"],"ar":["تصحيح أخطاء لينت","تشكيل الرمز","التوافق مع React وJavaScript","التكامل مع yarn prettier","تقارير الأخطاء والإصلاحات"]},"keywords":{"zh":["AI工具","代码修复","lint错误","格式问题","CI","React","JavaScript","yarn prettier","yarn linc"],"ja":["AIエージェント","コード修正","lintエラー","フォーマット問題","CI","React","JavaScript","yarn prettier","yarn linc"],"ko":["AI 에이전트","코드 수정","lint 오류","형식 문제","CI","React","JavaScript","yarn prettier","yarn linc"],"es":["herramientas de reparación de código","corrección de errores de lint","corrección de errores de formato","desarrollo de React","desarrollo de JavaScript","yarn prettier","yarn linc"],"fr":["outils de correction de code","correction des erreurs de lint","correction des erreurs de format","développement React","développement JavaScript","yarn prettier","yarn linc"],"de":["Code-Reparatur-Tools","Korrigieren von Lint-Fehlern","Korrigieren von Formatierungsfehlern","React-Entwicklung","JavaScript-Entwicklung","yarn prettier","yarn linc"],"pt":["ferramentas de IA","correção de erros de lint","formatação de código","React","JavaScript","yarn prettier","desenvolvimento de software","qualidade de código"],"ru":["ИИ агенты","исправление ошибок lint","форматирование кода","React","JavaScript","yarn prettier","разработка программного обеспечения","качество кода"],"ar":["أدوات الذكاء الاصطناعي","تصحيح أخطاء لينت","تشكيل الرمز","React","JavaScript","yarn prettier","تطوير البرمجيات","جودة الرمز"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Maintenance Agents needing to resolve lint errors and formatting issues in their codebase.","zh":"非常适合需要解决代码库中 lint 错误和格式化问题的代码维护代理。","ja":"コードベース内の lint エラーやフォーマットの問題を解決する必要があるコードメンテナンスエージェントに理想的です。","ko":"코드베이스의 린트 오류와 포맷팅 문제를 해결해야 하는 코드 유지보수 에이전트에 이상적입니다.","es":"Ideal para Agentes de Mantenimiento de Código que necesitan resolver errores de lint y problemas de formato en su base de código.","fr":"Idéal pour les agents de maintenance de code ayant besoin de résoudre les erreurs de lint et les problèmes de formatage dans leur base de code.","de":"Ideal für Code-Wartungsagenten, die Lint-Fehler und Formatierungsprobleme in ihrem Codebase beheben müssen.","pt":"Ideal para Agentes de Manutenção de Código que precisam resolver erros de lint e problemas de formatação em sua base de código.","ru":"Идеально для агентов по техническому обслуживанию кода, которым необходимо устранять ошибки lint и проблемы форматирования в их кодовой базе.","ar":"مثالي للوكلاء الذين يحتاجون إلى حل مشاكل التنسيق والتنسيق في قاعدة بياناتهم."},"recommendation":{"en":"Empowers agents to enforce code consistency by running `yarn prettier` for formatting and `yarn linc` for lint checks, ensuring compliance with CI standards and reducing manual fixes.","zh":"通过运行 `yarn prettier` 进行格式化和 `yarn linc` 进行 lint 检查，使代理能够强制执行代码一致性，确保符合 CI 标准并减少手动修复。","ja":"フォーマットには `yarn prettier` を、lint チェックには `yarn linc` を実行することで、エージェントがコードの一貫性を強制し、CI 標準への準拠を確保し、手動修正を減らすことを可能にします。","ko":"포맷팅을 위해 `yarn prettier`를, 린트 검사를 위해 `yarn linc`를 실행하여 에이전트가 코드 일관성을 강화하고 CI 표준을 준수하며 수동 수정을 줄일 수 있도록 합니다.","es":"Habilita a los agentes a hacer cumplir la coherencia del código ejecutando `yarn prettier` para el formato y `yarn linc` para las comprobaciones de lint, garantizando el cumplimiento de los estándares de CI y reduciendo las correcciones manuales.","fr":"Permet aux agents d''assurer la cohérence du code en exécutant `yarn prettier` pour la mise en forme et `yarn linc` pour les vérifications de lint, garantissant ainsi le respect des normes de CI et réduisant les corrections manuelles.","de":"Ermächtigt die Agenten, die Code-Konsistenz durch Ausführen von `yarn prettier` für die Formatierung und `yarn linc` für Lint-Prüfungen durchzusetzen, um die Einhaltung von CI-Standards sicherzustellen und manuelle Korrekturen zu reduzieren.","pt":"Habilita os agentes a impor a consistência do código executando `yarn prettier` para formatação e `yarn linc` para verificações de lint, garantindo a conformidade com os padrões de CI e reduzindo as correções manuais.","ru":"Наделяет агентов возможностью обеспечивать согласованность кода путем запуска `yarn prettier` для форматирования и `yarn linc` для проверок lint, обеспечивая соответствие стандартам CI и уменьшая ручные исправления.","ar":"تمكين الوكلاء من فرض الاتساق في الشفرة من خلال تشغيل `yarn prettier` للتنسيق و `yarn linc` للتحقق من lint ، مما يضمن الامتثال لمعايير CI وتقليل الإصلاحات اليدوية."},"useCases":{"en":["Automating code formatting with `yarn prettier`","Debugging lint errors using `yarn linc`","Validating code quality before committing"],"zh":["使用 `yarn prettier` 自动化代码格式化","使用 `yarn linc` 调试 lint 错误","在提交前验证代码质量"],"ja":["`yarn prettier` を使用したコードフォーマットの自動化","`yarn linc` を使用した lint エラーのデバッグ","コミット前のコード品質検証"],"ko":["`yarn prettier`로 코드 포맷팅 자동화","`yarn linc`를 사용하여 린트 오류 디버깅","커밋 전 코드 품질 검증"],"es":["Automatizar la formato de código con `yarn prettier`","Depurar errores de lint utilizando `yarn linc`","Validar la calidad del código antes de confirmar"],"fr":["Automatiser la mise en forme du code avec `yarn prettier`","Déboguer les erreurs de lint en utilisant `yarn linc`","Valider la qualité du code avant de valider"],"de":["Automatisieren der Code-Formatierung mit `yarn prettier`","Debuggen von Lint-Fehlern mit `yarn linc`","Validieren der Code-Qualität vor dem Commit"],"pt":["Automatizar a formatação de código com `yarn prettier`","Depurar erros de lint usando `yarn linc`","Validar a qualidade do código antes de comprometer"],"ru":["Автоматизация форматирования кода с помощью `yarn prettier`","Отладка ошибок lint с помощью `yarn linc`","Проверка качества кода перед фиксацией"],"ar":["تخصيص تنسيق الشفرة باستخدام `yarn prettier`","تصحيح أخطاء lint باستخدام `yarn linc`","التحقق من جودة الشفرة قبل الالتزام"]},"limitations":{"en":["Requires yarn package manager","Limited to projects with prettier and linc configurations"],"zh":["需要 yarn 包管理器","仅限于具有 prettier 和 linc 配置的项目"],"ja":["yarn パッケージマネージャーが必要","prettier および linc 設定がされているプロジェクトに限定される"],"ko":["yarn 패키지 관리자 필요","prettier 및 linc 구성이 있는 프로젝트로 제한됨"],"es":["Requiere el administrador de paquetes yarn","Limitado a proyectos con configuraciones de prettier y linc"],"fr":["Nécessite le gestionnaire de paquets yarn","Limité aux projets avec des configurations de prettier et de linc"],"de":["Benötigt den yarn-Paketmanager","Eingeschränkt auf Projekte mit prettier- und linc-Konfigurationen"],"pt":["Exige o gerenciador de pacotes yarn","Limitado a projetos com configurações de prettier e linc"],"ru":["Требуется менеджер пакетов yarn","Ограничен проектами с конфигурациями prettier и linc"],"ar":["يتطلب مدير الحزم yarn","محدود بمشاريع تكوين prettier و linc"]},"version":3},"contentHash":"a2edb0e8fb758efe98df7a4bc2bab1d82e46b1b40a5ad9cd45b60f44730e7c32","repoEtag":"W/\"516bff9f1eaeb5e7a0be7b0dd5e9952c46ecfd75e2420c65544a50b2412e72b0\"","qualityScore":73}');
