INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/fix', 'fix', 'facebook', 'react', 'official', 'fix facebook react official declarative frontend javascript library react ui fix代码修复工具，用于解决lint错误和格式问题，确保代码通过CI コード修正ツールfixは、lintエラーとフォーマット問題を解決し、コードがCIを通過できるようにします 코드 수정 도구 fix는 lint 오류 및 형식 문제를 해결하여 코드가 CI를 통과할 수 있도록 합니다 La habilidad de reparación de código es una herramienta para corregir errores de lint y formato en proyectos de React y JavaScript La compétence de correction de code est un outil pour corriger les erreurs de lint et de format dans les projets React et JavaScript Die Code-Reparaturfähigkeit ist ein Tool zum Korrigieren von Lint- und Formatierungsfehlern in React- und JavaScript-Projekten O agente de fix ajuda a corrigir erros de lint e formatação no seu código React e JavaScript, garantindo a qualidade e a consistência Агент исправления помогает исправить ошибки lint и форматирования в вашем коде React и JavaScript, гарантируя качество и согласованность وكيل الإصلاح يساعد في تصحيح أخطاء لينت وتشكيل في رمزك React وJavaScript، ضامنًا الجودة والاتساق Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI. AI工具 代码修复 lint错误 格式问题 CI React JavaScript yarn prettier yarn linc Use when you have lint errors, formatting issues, or before committing code to ensure it passes CI.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/flow', 'official', 'facebook', 'react', 'facebook/react', 'flow', 243408, 50622, 73, '2026-03-02T07:19:32Z', '2026-03-02T07:37:51.303Z', '4dcef83a65a5b702866f98922af5c56466e81e3e71809cf69c9292e182c2a685', '{"id":"facebook/react/flow","name":"flow","description":{"zh":"Flow类型检查是用于检查React代码类型错误的AI智能代理","ja":"FlowタイプチェックはReactコードのタイプエラーをチェックするAIエージェント","ko":"Flow 타입 체크는 React 코드의 타입 에러를 체크하는 AI 에이전트","es":"Flow es una herramienta de comprobación de tipos para React que ayuda a detectar errores de tipos en el código","fr":"Flow est un outil de vérification de types pour React qui aide à détecter les erreurs de types dans le code","de":"Flow ist ein Tool für die Typüberprüfung in React, das dabei hilft, Typfehler im Code zu erkennen","pt":"O Flow é uma ferramenta de verificação de tipo para React que ajuda a detectar erros de tipo em código JavaScript","ru":"Flow - это инструмент проверки типов для React, который помогает обнаруживать ошибки типов в коде JavaScript","ar":"Flow هو أداة للتحقق من النوع لمواقع React التي تساعد في الكشف عن أخطاء النوع في رمز JavaScript","en":"Use when you need to run Flow type checking, or when seeing Flow type errors in React code."},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243408,"forks":50622,"updatedAt":"2026-03-02T07:19:32Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"flow","description":"Use when you need to run Flow type checking, or when seeing Flow type errors in React code.","bodyPreview":"# Flow Type Checking\n\nArguments:\n- $ARGUMENTS: Renderer to check (default: dom-node)\n\n## Renderers\n\n| Renderer | When to Use |\n|----------|-------------|\n| `dom-node` | Default, recommended for most changes |\n| `dom-browser` | Browser-specific DOM code |\n| `native` | React Native |\n| `fabric` | React Native Fabric |\n\n## Instructions\n\n1. Run `yarn flow $ARGUMENTS` (use `dom-node` if no argument)\n2. Report type errors with file locations\n3. For comprehensive checking (slow), use `yarn flow-ci`\n\n##","body":"# Flow Type Checking\n\nArguments:\n- $ARGUMENTS: Renderer to check (default: dom-node)\n\n## Renderers\n\n| Renderer | When to Use |\n|----------|-------------|\n| `dom-node` | Default, recommended for most changes |\n| `dom-browser` | Browser-specific DOM code |\n| `native` | React Native |\n| `fabric` | React Native Fabric |\n\n## Instructions\n\n1. Run `yarn flow $ARGUMENTS` (use `dom-node` if no argument)\n2. Report type errors with file locations\n3. For comprehensive checking (slow), use `yarn flow-ci`\n\n## Common Mistakes\n\n- **Running without a renderer** - Always specify or use default `dom-node`\n- **Ignoring suppressions** - Check if `$FlowFixMe` comments are masking real issues\n- **Missing type imports** - Ensure types are imported from the correct package\n"},"category":"official","lastSynced":"2026-03-02T07:37:51.303Z","seo":{"title":{"zh":"AI智能代理 - Flow类型检查","ja":"AIエージェント - Flowタイプチェック","ko":"AI 에이전트 - Flow 타입 체크","es":"Herramientas de AI: Flujo de tipo de comprobación","fr":"Outils d''IA: Vérification de type Flow","de":"KI-Tools: Flow-Typüberprüfung","pt":"Ferramentas de IA: Flow Type Checking para React","ru":"ИИ Агенты: Проверка типов Flow для React","ar":"أدوات الذكاء الاصطناعي: Flow Type Checking ل React","en":"flow"},"description":{"zh":"Flow类型检查是用于检查React代码类型错误的AI智能代理","ja":"FlowタイプチェックはReactコードのタイプエラーをチェックするAIエージェント","ko":"Flow 타입 체크는 React 코드의 타입 에러를 체크하는 AI 에이전트","es":"Flow es una herramienta de comprobación de tipos para React que ayuda a detectar errores de tipos en el código","fr":"Flow est un outil de vérification de types pour React qui aide à détecter les erreurs de types dans le code","de":"Flow ist ein Tool für die Typüberprüfung in React, das dabei hilft, Typfehler im Code zu erkennen","pt":"O Flow é uma ferramenta de verificação de tipo para React que ajuda a detectar erros de tipo em código JavaScript","ru":"Flow - это инструмент проверки типов для React, который помогает обнаруживать ошибки типов в коде JavaScript","ar":"Flow هو أداة للتحقق من النوع لمواقع React التي تساعد في الكشف عن أخطاء النوع في رمز JavaScript","en":"Use when you need to run Flow type checking, or when seeing Flow type errors in React code."},"definition":{"en":"Use when you need to run Flow type checking, or when seeing Flow type errors in React code."},"features":{"zh":["支持React代码类型检查","提供详细的类型错误报告","支持多种渲染器","易于使用的命令行接口"],"ja":["Reactコードのタイプチェックをサポート","詳細なタイプエラー報告を提供","複数のレンダラーをサポート","使いやすいコマンドラインインターフェース"],"ko":["React 코드의 타입 체크를 지원","详细한 타입 에러 보고서를 제공","複数의 렌더러를 지원","사용하기 쉬운 명령줄 인터페이스"],"es":["Comprobación de tipos para React","Detección de errores de tipos","Compatibilidad con diferentes renderizadores","Opciones de comprobación personalizadas","Integración con yarn"],"fr":["Vérification de types pour React","Détection des erreurs de types","Compatibilité avec différents renderers","Options de vérification personnalisées","Intégration avec yarn"],"de":["Typüberprüfung für React","Erkennung von Typfehlern","Kompatibilität mit verschiedenen Renderern","Benutzerdefinierte Überprüfungsoptionen","Integration mit yarn"],"pt":["Verificação de tipo para código React","Suporte a diferentes renderizadores (dom-node, dom-browser, native, fabric)","Comando `yarn flow` para verificar erros de tipo","Comando `yarn flow-ci` para verificação completa (lenta)","Relatórios de erros com localização de arquivo"],"ru":["Проверка типов для кода React","Поддержка разных рендереров (dom-node, dom-browser, native, fabric)","Команда `yarn flow` для проверки ошибок типов","Команда `yarn flow-ci` для полной проверки (медленной)","Отчеты об ошибках с указанием местоположения файла"],"ar":["التحقق من النوع لرمز React","دعم لمحسّنات العرض المختلفة (dom-node، dom-browser، native، fabric)","أمر `yarn flow` للتحقق من أخطاء النوع","أمر `yarn flow-ci` للتحقق الكامل (ببطء)","تقارير بالأخطاء مع إظهار موقع الملف"]},"keywords":{"zh":["Flow类型检查","React代码类型错误","JavaScript类型检查","AI智能代理","代码质量","类型安全"],"ja":["Flowタイプチェック","Reactコードのタイプエラー","JavaScriptタイプチェック","AIエージェント","コード品質","タイプセーフティ"],"ko":["Flow 타입 체크","React 코드의 타입 에러","JavaScript 타입 체크","AI 에이전트","코드 품질","타입 안전"],"es":["Flow","comprobación de tipos","React","errores de tipos","herramientas de desarrollo","yarn","renderizadores"],"fr":["Flow","vérification de types","React","erreurs de types","outils de développement","yarn","renderers"],"de":["Flow","Typüberprüfung","React","Typfehler","Entwicklungstools","yarn","Renderer"],"pt":["Flow","React","verificação de tipo","JavaScript","desenvolvimento frontend","ferramentas de desenvolvimento","erros de tipo","qualidade de código"],"ru":["Flow","React","проверка типов","JavaScript","разработка frontend","инструменты разработки","ошибки типов","качество кода"],"ar":["Flow","React","التحقق من النوع","JavaScript","تطوير frontend","أدوات التطوير","أخطاء النوع","جودة الرمز"]}},"agentAnalysis":{"suitability":{"en":"Perfect for React Development Agents needing advanced Flow type checking capabilities.","zh":"非常适合需要高级 Flow 类型检查功能的 React 开发代理。","ja":"高度な Flow 型チェック機能を必要とする React 開発エージェントに最適です。","ko":"고급 Flow 타입 검사 기능이 필요한 React 개발 에이전트에 완벽합니다.","es":"Perfecto para agentes de desarrollo de React que necesitan capacidades avanzadas de verificación de tipos Flow.","fr":"Parfait pour les agents de développement React nécessitant des capacités de vérification de type Flow avancées.","de":"Perfekt für React-Entwicklungsagenten, die erweiterte Flow-Typüberprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento React que necessitam de capacidades avançadas de verificação de tipo Flow.","ru":"Идеально для агентов разработки React, которым необходимы расширенные возможности проверки типа Flow.","ar":"مثالي لعميل التطوير React الذي يحتاج إلى إمكانيات متقدمة لتحقق نوع التدفق."},"recommendation":{"en":"Empowers agents to run Flow type checking on React code, utilizing renderers like dom-node, dom-browser, native, and fabric, and report type errors with file locations using yarn flow and yarn flow-ci commands.","zh":"使代理能够对 React 代码运行 Flow 类型检查，利用 dom-node、dom-browser、native 和 fabric 等渲染器，并使用 yarn flow 和 yarn flow-ci 命令报告带有文件位置的类型错误。","ja":"React コードで Flow 型チェックを実行し、dom-node、dom-browser、native、fabric などのレンダラーを利用し、yarn flow および yarn flow-ci コマンドを使用してファイル位置を含む型エラーを報告することをエージェントに可能にします。","ko":"에이전트가 React 코드에서 Flow 타입 검사를 실행하고, dom-node, dom-browser, native 및 fabric과 같은 렌더러를 활용하며, yarn flow 및 yarn flow-ci 명령을 사용하여 파일 위치가 포함된 타입 오류를 보고할 수 있도록 합니다.","es":"Habilita a los agentes para ejecutar la verificación de tipos Flow en el código React, utilizando renderizadores como dom-node, dom-browser, native y fabric, e informar errores de tipo con ubicaciones de archivos utilizando los comandos yarn flow y yarn flow-ci.","fr":"Permet aux agents d''exécuter la vérification de type Flow sur le code React, en utilisant des renderers tels que dom-node, dom-browser, native et fabric, et de signaler les erreurs de type avec des emplacements de fichiers en utilisant les commandes yarn flow et yarn flow-ci.","de":"Ermöglich es den Agenten, die Flow-Typüberprüfung auf React-Code auszuführen, indem sie Renderer wie dom-node, dom-browser, native und fabric verwenden und Typfehler mit Dateispeicherorten mithilfe der Befehle yarn flow und yarn flow-ci zu melden.","pt":"Habilita os agentes a executar a verificação de tipo Flow no código React, utilizando renderizadores como dom-node, dom-browser, native e fabric, e relatar erros de tipo com localizações de arquivo usando os comandos yarn flow e yarn flow-ci.","ru":"Наделяет агентов возможностью запускать проверку типа Flow для кода React, используя рендереры seperti dom-node, dom-browser, native и fabric, и сообщать об ошибках типа с местоположением файла, используя команды yarn flow и yarn flow-ci.","ar":"يمنح الوكيل khảية تشغيل التحقق من نوع التدفق على رمز التفاعل، باستخدام محركات العرض مثل dom-node و dom-browser و native و fabric، وتقديم تقارير عن أخطاء النوع مع مواقع الملفات باستخدام أوامر yarn flow و yarn flow-ci."},"useCases":{"en":["Debugging Flow type errors in React applications","Running comprehensive type checking on React Native projects","Validating browser-specific DOM code using dom-browser renderer"],"zh":["调试 React 应用程序中的 Flow 类型错误","对 React Native 项目运行全面的类型检查","使用 dom-browser 渲染器验证浏览器特定的 DOM 代码"],"ja":["React アプリケーションにおける Flow 型エラーのデバッグ","React Native プロジェクトでの包括的な型チェックの実行","dom-browser レンダラーを使用したブラウザ固有の DOM コードの検証"],"ko":["React 애플리케이션에서 Flow 타입 오류 디버깅","React Native 프로젝트에서 포괄적인 타입 검사 실행","dom-browser 렌더러를 사용하여 브라우저별 DOM 코드 검증"],"es":["Depuración de errores de tipo Flow en aplicaciones React","Ejecución de una verificación de tipo integral en proyectos React Native","Validación de código DOM específico del navegador utilizando el renderizador dom-browser"],"fr":["Débogage des erreurs de type Flow dans les applications React","Exécution d''une vérification de type complète sur les projets React Native","Validation du code DOM spécifique au navigateur en utilisant le renderizador dom-browser"],"de":["Debuggen von Flow-Typfehlern in React-Anwendungen","Ausführen einer umfassenden Typüberprüfung in React Native-Projekten","Validierung von browser-spezifischem DOM-Code unter Verwendung des dom-browser-Renderers"],"pt":["Depuração de erros de tipo Flow em aplicações React","Execução de verificação de tipo abrangente em projetos React Native","Validação de código DOM específico do navegador usando o renderizador dom-browser"],"ru":["Отладка ошибок типа Flow в приложениях React","Запуск полной проверки типа в проектах React Native","Проверка кода DOM, специфичного для браузера, с помощью рендерера dom-browser"],"ar":["تصحيح أخطاء نوع التدفق في تطبيقات React","تشغيل التحقق الشامل من النوع في مشاريع React Native","التحقق من صحة رمز DOM المحدد للمتصفح باستخدام محرك العرض dom-browser"]},"limitations":{"en":["Requires yarn package manager","Limited to React and React Native projects","May require additional setup for comprehensive checking with yarn flow-ci"],"zh":["需要 yarn 包管理器","仅限于 React 和 React Native 项目","使用 yarn flow-ci 进行全面检查可能需要额外设置"],"ja":["yarn パッケージマネージャーが必要","React および React Native プロジェクトに限定","yarn flow-ci を使用した包括的なチェックには追加の設定が必要な場合があります"],"ko":["yarn 패키지 관리자 필요","React 및 React Native 프로젝트로 제한됨","yarn flow-ci를 사용한 포괄적인 검사에 추가 설정이 필요할 수 있음"],"es":["Requiere el administrador de paquetes yarn","Limitado a proyectos React y React Native","Puede requerir una configuración adicional para una verificación integral con yarn flow-ci"],"fr":["Nécessite le gestionnaire de paquets yarn","Limité aux projets React et React Native","Peut nécessiter une configuration supplémentaire pour une vérification complète avec yarn flow-ci"],"de":["Benötigt den Paket-Manager yarn","Begrenzt auf React- und React Native-Projekte","Kann eine zusätzliche Konfiguration für eine umfassende Überprüfung mit yarn flow-ci erfordern"],"pt":["Exige o gerenciador de pacotes yarn","Limitado a projetos React e React Native","Pode exigir configuração adicional para verificação abrangente com yarn flow-ci"],"ru":["Требует менеджера пакетов yarn","Ограничен проектами React и React Native","Может требовать дополнительной настройки для полной проверки с помощью yarn flow-ci"],"ar":["يتطلب مدير الحزم yarn","محدود بمشاريع React و React Native","يمكن أن يتطلب إعدادات إضافية للتحقق الشامل باستخدام yarn flow-ci"]},"version":3},"contentHash":"4dcef83a65a5b702866f98922af5c56466e81e3e71809cf69c9292e182c2a685","repoEtag":"W/\"516bff9f1eaeb5e7a0be7b0dd5e9952c46ecfd75e2420c65544a50b2412e72b0\"","qualityScore":73}');
