INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/verify', 'official', 'facebook', 'react', 'facebook/react', 'verify', 243408, 50622, 73, '2026-03-02T07:19:32Z', '2026-03-02T07:37:52.051Z', '070d8a87c34b661d98c7b8d72b4443706c4f78386647b115476d34121e70d0be', '{"id":"facebook/react/verify","name":"verify","description":{"zh":"verify技能用于验证React代码更改，确保代码符合贡献要求","ja":"verifyスキルはReactコードの変更を検証し、コードが貢献要件を満たしていることを確認","ko":"verify 기능은 React 코드 변경을 검증하여 코드가 기여 요구 사항을 충족하는지 확인","es":"La herramienta de verificación de AI ayuda a validar cambios en proyectos React antes de comprometerlos, garantizando la calidad del código","fr":"L''outil de vérification de l''agent IA aide à valider les modifications des projets React avant de les valider, assurant la qualité du code","de":"Das KI-Überprüfungstool hilft bei der Validierung von Änderungen in React-Projekten, bevor sie committet werden, und stellt die Code-Qualität sicher","pt":"A habilidade de verificação é usada para validar alterações antes de commitar, garantindo que todas as contribuições do React estejam de acordo com os requisitos","ru":"Навык верификации используется для проверки изменений перед коммитом, гарантируя, что все вклады в React соответствуют требованиям","ar":"تستخدم مهارة التحقق لتحقق التغييرات قبل الإلتزام، وضمان أن جميع المساهمات في React تتوافق مع المتطلبات","en":"Use when you want to validate changes before committing, or when you need to check all React contribution requirements."},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243408,"forks":50622,"updatedAt":"2026-03-02T07:19:32Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"verify","description":"Use when you want to validate changes before committing, or when you need to check all React contribution requirements.","bodyPreview":"# Verification\n\nRun all verification steps.\n\nArguments:\n- $ARGUMENTS: Test pattern for the test step\n\n## Instructions\n\nRun these first in sequence:\n1. Run `yarn prettier` - format code (stop if fails)\n2. Run `yarn linc` - lint changed files (stop if fails)\n\nThen run these with subagents in parallel:\n1. Use `/flow` to type check (stop if fails)\n2. Use `/test` to test changes in source (stop if fails)\n3. Use `/test www` to test changes in www (stop if fails)\n\nIf all pass, show success summary. On","body":"# Verification\n\nRun all verification steps.\n\nArguments:\n- $ARGUMENTS: Test pattern for the test step\n\n## Instructions\n\nRun these first in sequence:\n1. Run `yarn prettier` - format code (stop if fails)\n2. Run `yarn linc` - lint changed files (stop if fails)\n\nThen run these with subagents in parallel:\n1. Use `/flow` to type check (stop if fails)\n2. Use `/test` to test changes in source (stop if fails)\n3. Use `/test www` to test changes in www (stop if fails)\n\nIf all pass, show success summary. On failure, stop immediately and report the issue with suggested fixes.\n"},"category":"official","lastSynced":"2026-03-02T07:37:52.051Z","seo":{"title":{"zh":"AI智能代理verify技能","ja":"AIエージェントのverifyスキル","ko":"AI 에이전트 verify 기능","es":"Herramientas de verificación de AI: Validación de cambios...","fr":"Outils d''agent IA pour la vérification: Validation des mo...","de":"KI-Tools für die Überprüfung: Änderungsvalidierung mit React","pt":"Ferramentas de IA: Verificar Alterações com React","ru":"ИИ Агенты: Верификация Изменений с React","ar":"أدوات الذكاء الاصطناعي: التحقق من التغييرات مع React","en":"verify"},"description":{"zh":"verify技能用于验证React代码更改，确保代码符合贡献要求","ja":"verifyスキルはReactコードの変更を検証し、コードが貢献要件を満たしていることを確認","ko":"verify 기능은 React 코드 변경을 검증하여 코드가 기여 요구 사항을 충족하는지 확인","es":"La herramienta de verificación de AI ayuda a validar cambios en proyectos React antes de comprometerlos, garantizando la calidad del código","fr":"L''outil de vérification de l''agent IA aide à valider les modifications des projets React avant de les valider, assurant la qualité du code","de":"Das KI-Überprüfungstool hilft bei der Validierung von Änderungen in React-Projekten, bevor sie committet werden, und stellt die Code-Qualität sicher","pt":"A habilidade de verificação é usada para validar alterações antes de commitar, garantindo que todas as contribuições do React estejam de acordo com os requis...","ru":"Навык верификации используется для проверки изменений перед коммитом, гарантируя, что все вклады в React соответствуют требованиям","ar":"تستخدم مهارة التحقق لتحقق التغييرات قبل الإلتزام، وضمان أن جميع المساهمات في React تتوافق مع المتطلبات","en":"Use when you want to validate changes before committing, or when you need to check all React contribution requirements."},"definition":{"en":"Use when you want to validate changes before committing, or when you need to check all React contribution requirements."},"features":{"zh":["验证React代码更改","检查代码格式和风格","执行lint和类型检查","运行测试用例","支持并行执行"],"ja":["Reactコードの変更を検証","コードのフォーマットとスタイルをチェック","lintと型チェックを実行","テストケースを実行","並行実行をサポート"],"ko":["React 코드 변경을 검증","코드 형식과 스타일을 확인","lint와 타입 검사를 실행","테스트 케이스를 실행","병렬 실행을 지원"],"es":["Validación de cambios antes de comprometerlos","Comprobación de formato de código con yarn prettier","Análisis de errores con yarn linc","Verificación de tipos con /flow","Pruebas de cambios en la fuente y en www"],"fr":["Validation des modifications avant de les valider","Vérification du formatage du code avec yarn prettier","Analyse des erreurs avec yarn linc","Vérification des types avec /flow","Tests des modifications dans la source et dans www"],"de":["Validierung von Änderungen vor dem Committen","Überprüfung des Code-Formats mit yarn prettier","Fehleranalyse mit yarn linc","Typüberprüfung mit /flow","Tests von Änderungen in der Quelle und in www"],"pt":["Executa o yarn prettier para formatar o código","Executa o yarn linc para verificar os arquivos alterados","Realiza verificação de tipo com o flow","Realiza testes de alterações na fonte e no www","Exibe um resumo de sucesso se todos os testes passarem"],"ru":["Выполняет yarn prettier для форматирования кода","Выполняет yarn linc для проверки измененных файлов","Осуществляет проверку типа с помощью flow","Осуществляет тестирование изменений в источнике и в www","Отображает сводку успеха, если все тесты пройдены"],"ar":["ينفذ يارن بريتي لتنسيق الكود","ينفذ يارن لينك لتحقق من الملفات المعدلة","يقوم بالتحقق من النوع باستخدام الفلو","يقوم باختبار التغييرات في المصدر والويب","يعرض ملخص النجاح إذا نجح جميع الاختبارات"]},"keywords":{"zh":["AI智能代理","verify技能","React代码验证","代码质量","代码安全","自动化测试","并行执行"],"ja":["AIエージェント","verifyスキル","Reactコード検証","コード品質","コードセキュリティ","自動テスト","並行実行"],"ko":["AI 에이전트","verify 기능","React 코드 검증","코드 품질","코드 보안","자동화 테스트","병렬 실행"],"es":["herramientas de verificación de AI","validación de cambios en React","yarn prettier","yarn linc","verificación de tipos","pruebas de cambios en la fuente","pruebas de cambios en www","desarrollo de software","calidad del código"],"fr":["outils de vérification de l''agent IA","validation des modifications dans React","yarn prettier","yarn linc","vérification des types","tests des modifications dans la source","tests des modifications dans www","développement de logiciels","qualité du code"],"de":["KI-Überprüfungstools","Validierung von Änderungen in React","yarn prettier","yarn linc","Typüberprüfung","Tests von Änderungen in der Quelle","Tests von Änderungen in www","Software-Entwicklung","Code-Qualität"],"pt":["ferramentas de ia","verificação de código","react","yarn prettier","yarn linc","flow","testes de alterações","desenvolvimento de software"],"ru":["ии агенты","верификация кода","react","yarn prettier","yarn linc","flow","тестирование изменений","разработка программного обеспечения"],"ar":["أدوات الذكاء الاصطناعي","تحقق الكود","ري액ت","يارن بريتي","يارن لينك","الفلو","اختبار التغييرات","تطوير البرمجيات"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated validation and testing of React contributions.","zh":"非常适合需要自动验证和测试 React 贡献的代码审查代理","ja":"React の貢献の自動検証とテストが必要なコードレビューエージェントに最適","ko":"리액트 기여의 자동 검증 및 테스트가 필요한 코드 리뷰 에이전트에 적합합니다","es":"Perfecto para Agentes de Revisión de Código que necesitan validación y prueba automatizadas de contribuciones de React.","fr":"Parfait pour les Agents de Revue de Code nécessitant une validation et des tests automatisés de contributions React.","de":"Perfekt für Code-Review-Agents, die eine automatisierte Überprüfung und Tests von React-Beiträgen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de validação e teste automatizados de contribuições do React.","ru":"Идеально подходит для агентов по проверке кода, которым требуется автоматическая проверка и тестирование вкладов в React.","ar":"مثالي لوكلاء مراجعة الشفرة الذين يحتاجون إلى التحقق والاختبار الآلي للمساهمات في React."},"recommendation":{"en":"Empowers agents to validate code changes using yarn prettier for formatting, yarn linc for linting, and parallel testing with /flow, /test, and /test www, ensuring compliance with React contribution requirements.","zh":"赋予代理验证代码更改的能力，使用 yarn prettier 进行格式化，yarn linc 进行 linting，并使用 /flow、/test 和 /test www 进行并行测试，确保符合 React 贡献要求","ja":"yarn prettier でフォーマット、yarn linc で linting を行い、/flow、/test、/test www で並列テストを実行することで、React 貢献要件に準拠したコード変更の検証が可能","ko":"yarn prettier로 포맷팅하고, yarn linc로 linting을 수행하며, /flow, /test, /test www로 병렬 테스트를 수행하여 리액트 기여 요구 사항을 준수하는 코드 변경 사항을 검증할 수 있는 에이전트를 활성화합니다","es":"Habilita a los agentes a validar cambios de código utilizando yarn prettier para la formateo, yarn linc para la verificación de normas y pruebas paralelas con /flow, /test y /test www, garantizando el cumplimiento de los requisitos de contribución de React.","fr":"Permet aux agents de valider les modifications de code en utilisant yarn prettier pour le formatage, yarn linc pour la vérification des règles et les tests parallèles avec /flow, /test et /test www, garantissant ainsi le respect des exigences de contribution React.","de":"Ermächtigt die Agenten, Codeänderungen zu überprüfen, indem sie yarn prettier für die Formatierung, yarn linc für die Prüfung von Vorschriften und parallele Tests mit /flow, /test und /test www verwenden, um die Einhaltung der React-Beitrittsanforderungen sicherzustellen.","pt":"Habilita os agentes a validar alterações de código usando yarn prettier para formatação, yarn linc para verificação de erros e testes paralelos com /flow, /test e /test www, garantindo a conformidade com os requisitos de contribuição do React.","ru":"Позволяет агентам проверять изменения кода с помощью yarn prettier для форматирования, yarn linc для проверки ошибок и параллельного тестирования с /flow, /test и /test www, обеспечивая соответствие требованиям вклада в React.","ar":"تمكن الوكلاء من التحقق من تغييرات الشفرة باستخدام yarn prettier لتنسيق الشفرة، وyarn linc للتحقق من الأخطاء، واختبارات متوازية مع /flow، /test، و/test www، مما يضمن امتثالها لمتطلبات المساهمة في React."},"useCases":{"en":["Automating code formatting checks with yarn prettier","Validating React code contributions against linting rules with yarn linc","Parallelizing test runs for source and www changes"],"zh":["使用 yarn prettier 自动进行代码格式检查","使用 yarn linc 验证 React 代码贡献是否符合 linting 规则","并行运行源代码和 www 更改的测试"],"ja":["yarn prettier を使用してコードのフォーマットチェックを自動化する","yarn linc を使用して React コードの貢献が linting ルールに準拠していることを検証する","ソースコードと www の変更のテストを並列で実行する"],"ko":["yarn prettier를 사용하여 코드 형식 체크를 자동화하는 것","yarn linc를 사용하여 리액트 코드 기여가 린팅 규칙을 준수하는지 확인하는 것","소스 코드 및 www 변경 사항에 대한 테스트를 병렬로 실행하는 것"],"es":["Automatizar las comprobaciones de formato de código con yarn prettier","Validar las contribuciones de código React contra las reglas de verificación con yarn linc","Parallelizar las ejecuciones de pruebas para cambios de origen y www"],"fr":["Automatiser les vérifications de formatage de code avec yarn prettier","Valider les contributions de code React par rapport aux règles de vérification avec yarn linc","Paralléliser les exécutions de tests pour les modifications de source et www"],"de":["Automatisieren von Code-Formatierungsprüfungen mit yarn prettier","Überprüfen von React-Codebeiträgen gegenüber Lint-Regeln mit yarn linc","Parallelisieren von Testläufen für Quell- und www-Änderungen"],"pt":["Automatizar verificações de formatação de código com yarn prettier","Validar contribuições de código React contra regras de verificação de erros com yarn linc","Paralelizar execuções de testes para alterações de origem e www"],"ru":["Автоматизировать проверку форматирования кода с помощью yarn prettier","Проверять вклады кода React против правил проверки ошибок с помощью yarn linc","Параллелизировать запуски тестов для изменений источника и www"],"ar":["تأتميت التحقق من تنسيق الشفرة باستخدام yarn prettier","التحقق من مساهمات الشفرة React ضد قواعد التحقق من الأخطاء باستخدام yarn linc","توزيع تشغيل الاختبارات لتحديثات المصدر وwww"]},"limitations":{"en":["Requires yarn installed","Limited to React codebase validation","Dependent on /flow, /test, and /test www subagents"],"zh":["需要安装 yarn","仅限 React 代码库验证","依赖于 /flow、/test 和 /test www 子代理"],"ja":["yarn のインストールが必要","React コードベースの検証のみ","/flow、/test、/test www サブエージェントに依存"],"ko":["yarn을 설치해야 함","리액트 코드베이스의 검증만 가능","/flow, /test, /test www 서브 에이전트에 의존"],"es":["Requiere yarn instalado","Limitado a la validación de la base de código React","Dependiente de los subagentes /flow, /test y /test www"],"fr":["Nécessite yarn installé","Limité à la validation de la base de code React","Dépendant des sous-agents /flow, /test et /test www"],"de":["Benötigt yarn installiert","Begrenzt auf die Validierung der React-Codebasis","Abhängig von den Subagenten /flow, /test und /test www"],"pt":["Requer yarn instalado","Limitado à validação da base de código React","Dependente dos subagentes /flow, /test e /test www"],"ru":["Требует установленного yarn","Ограничен проверкой базы кода React","Зависит от субагентов /flow, /test и /test www"],"ar":["يتطلب تثبيت yarn","محدود بالتحقق من قاعدة الشفرة React","يعتمد على وكلاء فرعيين /flow، /test، و/test www"]},"version":3},"contentHash":"070d8a87c34b661d98c7b8d72b4443706c4f78386647b115476d34121e70d0be","repoEtag":"W/\"516bff9f1eaeb5e7a0be7b0dd5e9952c46ecfd75e2420c65544a50b2412e72b0\"","qualityScore":73}');
